const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const scroller=$('#scroller'),menu=$('#menu'),burger=$('.burger');let toastTimer;
function notice(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function setMenu(open){document.body.classList.toggle('menu-open',open);burger.setAttribute('aria-expanded',String(open));burger.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');menu.inert=!open;menu.setAttribute('aria-hidden',String(!open));scroller.inert=open;scroller.style.overflowY=open?'hidden':'';if(open)setTimeout(()=>menu.querySelector('a').focus(),100);else burger.focus()}
burger.onclick=()=>setMenu(!document.body.classList.contains('menu-open'));$$('.menu nav>*').forEach((x,i)=>x.style.setProperty('--i',i));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('menu-open'))setMenu(false);if(e.key==='Tab'&&document.body.classList.contains('menu-open')){const focus=[burger,...menu.querySelectorAll('a,button')];if(e.shiftKey&&document.activeElement===focus[0]){e.preventDefault();focus.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===focus.at(-1)){e.preventDefault();burger.focus()}}});
$$('[data-notice]').forEach(el=>el.onclick=()=>notice(el.dataset.notice));
$$('a[href^="#"]').forEach(el=>el.addEventListener('click',e=>{if(el.getAttribute('href').startsWith('#/'))return;const target=$(el.getAttribute('href'));if(!target)return;e.preventDefault();if(document.body.classList.contains('menu-open'))setMenu(false);window.SiteMotion.goTo(target);history.replaceState(null,'',document.querySelector('#about-page').hidden?el.getAttribute('href'):'#/about');if(el.dataset.service){$('#brief-form [name="business"]').value=el.dataset.service}}));
const caseItems=[1,2,3];let activeCase=1;
function positionCases(){if($('#home-page').hidden)return;const track=$('#case-track'),cards=$$('.case-card');const card=cards[activeCase];track.style.transform=`translateX(${(track.parentElement.clientWidth-card.offsetWidth)/2-card.offsetLeft}px)`}
function selectCase(index){activeCase=(index+caseItems.length)%caseItems.length;$$('.case-card').forEach((el,i)=>{el.classList.toggle('selected',i===activeCase);el.setAttribute('aria-pressed',String(i===activeCase))});$('#case-count').textContent=`.. ${String(activeCase+1).padStart(2,'0')} ..`;positionCases();window.CaseBackground.select(activeCase);}

$('#previous-case').onclick=()=>selectCase(activeCase-1);$('#next-case').onclick=()=>selectCase(activeCase+1);$$('.case-card').forEach(el=>el.onclick=()=>selectCase(+el.dataset.case));$('#cases').addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();selectCase(activeCase+1)}if(e.key==='ArrowLeft'){e.preventDefault();selectCase(activeCase-1)}});
let touchX=null,touchY=null;$('#case-track').addEventListener('touchstart',e=>{touchX=e.touches[0].clientX;touchY=e.touches[0].clientY},{passive:true});$('#case-track').addEventListener('touchend',e=>{if(touchX===null)return;const d=e.changedTouches[0].clientX-touchX;if(Math.abs(d)>45&&Math.abs(d)>Math.abs(e.changedTouches[0].clientY-touchY))selectCase(activeCase+(d<0?1:-1));touchX=null},{passive:true});
$('#sound').onclick=()=>window.CaseBackground.toggleSound();
const serviceTrack=$('#services-track');let serviceTimer;function serviceStep(delta){const step=$('.service').offsetWidth+parseFloat(getComputedStyle(serviceTrack).gap);serviceTrack.scrollBy({left:delta*step,behavior:'smooth'})}$('#previous-service').onclick=()=>serviceStep(-1);$('#next-service').onclick=()=>serviceStep(1);serviceTrack.addEventListener('scroll',()=>{serviceTrack.classList.add('moving');clearTimeout(serviceTimer);serviceTimer=setTimeout(()=>serviceTrack.classList.remove('moving'),120);const step=$('.service').offsetWidth+parseFloat(getComputedStyle(serviceTrack).gap);$('#service-count').textContent=String(Math.min(4,Math.round(serviceTrack.scrollLeft/step)+1)).padStart(2,'0')+' / 04'},{passive:true});serviceTrack.addEventListener('wheel',e=>{if(Math.abs(e.deltaY)>Math.abs(e.deltaX)&&((e.deltaY>0&&serviceTrack.scrollLeft<serviceTrack.scrollWidth-serviceTrack.clientWidth-2)||(e.deltaY<0&&serviceTrack.scrollLeft>2))){e.preventDefault();e.stopPropagation();serviceTrack.scrollBy({left:e.deltaY,behavior:'auto'})}},{passive:false});
$('#brief-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const body=`Имя: ${data.get('name')}\nТелефон: ${data.get('phone')}\nТип бизнеса: ${data.get('business')}`;const link=document.createElement('a');link.href=`mailto:filming@gmail.com?subject=${encodeURIComponent('Заявка на создание видео')}&body=${encodeURIComponent(body)}`;link.click();$('#form-status').textContent='Открываем почтовое приложение с вашей заявкой. Отправьте письмо, чтобы связаться с нами.'});
addEventListener('resize',positionCases);document.fonts.ready.then(positionCases);selectCase(1);
